    if (size <= 0) {
        return;
    }
    final int currentCapacity = array.length;
    final int needed = this.size + size;
    if (currentCapacity >= needed) {
        return;
    }
    int newCapacity = currentCapacity == 0 ? Math.max(8, needed) : currentCapacity << 1;
    while (newCapacity < needed) {
        newCapacity <<= 1;
    }
    final byte[] newArray = new byte[newCapacity];
    System.arraycopy(array, 0, newArray, 0, this.size);
    array = newArray;
}

